INSERT INTO `message_templates` (`id`, `name`, `channel`, `language`, `body`, `provider_template_id`, `params`, `active`, `created_at`) VALUES (1,'Polling day reminder','SMS','en','Dear {name}, please vote on polling day. Your booth: {boothNo} {boothName}, serial no. {serialNo}. - Jan Vikas Party','1107170000000000001','name,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000'),
(2,'मतदान दिवस अनुस्मारक','SMS','hi','प्रिय {nameLocal}, कृपया मतदान अवश्य करें। आपका बूथ: {boothNo} {boothName}, क्रम सं. {serialNo}। - जन विकास पार्टी','1107170000000000002','nameLocal,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000'),
(3,'ووٹنگ یاد دہانی','SMS','ur','محترم {nameLocal}، براہ کرم ووٹ ضرور دیں۔ آپ کا بوتھ: {boothNo} {boothName}، سیریل نمبر {serialNo}۔','1107170000000000003','nameLocal,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000'),
(4,'ভোটের অনুস্মারক','SMS','bn','প্রিয় {nameLocal}, অনুগ্রহ করে ভোট দিন। আপনার বুথ: {boothNo} {boothName}, ক্রম নং {serialNo}।','1107170000000000004','nameLocal,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000'),
(5,'Booth slip','WHATSAPP','en','Namaste {name}! Your voter slip: EPIC {epicNo}, booth {boothNo} ({boothName}), serial {serialNo}.','voter_slip','name,epicNo,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000'),
(6,'बूथ पर्ची','WHATSAPP','hi','नमस्ते {nameLocal}! आपकी मतदाता पर्ची: EPIC {epicNo}, बूथ {boothNo} ({boothName}), क्रम सं. {serialNo}।','voter_slip','nameLocal,epicNo,boothNo,boothName,serialNo','','2026-11-15 15:09:48.000000');
