CREATE TABLE `voters` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `epic_no` varchar(20) NOT NULL,
  `name` varchar(120) NOT NULL COMMENT 'name as on the roll (English)',
  `name_local` varchar(120) DEFAULT NULL COMMENT 'name in the regional language',
  `relative_name` varchar(120) DEFAULT NULL,
  `relative_name_local` varchar(120) DEFAULT NULL,
  `relation_type` varchar(10) DEFAULT NULL,
  `gender` varchar(10) NOT NULL,
  `age` int(11) DEFAULT NULL,
  `assembly_no` int(11) NOT NULL,
  `assembly_name` varchar(100) DEFAULT NULL,
  `booth_no` int(11) NOT NULL,
  `booth_name` varchar(200) DEFAULT NULL,
  `serial_no` int(11) DEFAULT NULL,
  `house_no` varchar(30) DEFAULT NULL,
  `address` varchar(300) DEFAULT NULL,
  `address_local` varchar(300) DEFAULT NULL,
  `village_ward` varchar(100) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `pincode` varchar(6) DEFAULT NULL,
  `mobile` varchar(10) DEFAULT NULL,
  `alt_mobile` varchar(10) DEFAULT NULL,
  `email` varchar(120) DEFAULT NULL,
  `category` varchar(50) DEFAULT NULL,
  `remarks` varchar(500) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_voter_epic` (`epic_no`),
  KEY `idx_voter_name` (`name`),
  KEY `idx_voter_name_local` (`name_local`),
  KEY `idx_voter_assembly_booth` (`assembly_no`,`booth_no`),
  KEY `idx_voter_mobile` (`mobile`),
  KEY `idx_voter_district` (`district`),
  KEY `idx_voter_village` (`village_ward`)
) ENGINE=InnoDB AUTO_INCREMENT=2061 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
